abstract class ParameterHandler<T> {
  abstract void apply(RequestBuilder builder, @Nullable T value) throws IOException;

  final ParameterHandler<Iterable<T>> iterable() {
    return new ParameterHandler<Iterable<T>>() {
      @Override
      void apply(RequestBuilder builder, @Nullable Iterable<T> values) throws IOException {
        if (values == null) return; // Skip null values.

        for (T value : values) {
          ParameterHandler.this.apply(builder, value);
        }
      }
    };
  }

  final ParameterHandler<Object> array() {
    return new ParameterHandler<Object>() {
      @Override
      void apply(RequestBuilder builder, @Nullable Object values) throws IOException {
        if (values == null) return; // Skip null values.

        for (int i = 0, size = Array.getLength(values); i < size; i++) {
          //noinspection unchecked
          ParameterHandler.this.apply(builder, (T) Array.get(values, i));
        }
      }
    };
  }

  private static <T> void applyStringMap(
      Method method,
      int p,
      @Nullable Map<String, T> map,
      String mapName,
      Converter<T, String> converter,
      BiConsumer<String, String> action) throws IOException {
    if (map == null) {
      throw Utils.parameterError(method, p, "%s map was null.", mapName);
    }
    for (Map.Entry<String, T> entry : map.entrySet()) {
      String key = entry.getKey();
      if (key == null) {
        throw Utils.parameterError(method, p, "%s map contained null key.", mapName);
      }
      T value = entry.getValue();
      if (value == null) {
        throw Utils.parameterError(
            method, p, "%s map contained null value for key '%s'.", mapName, key);
      }
      String converted = converter.convert(value);
      if (converted == null) {
        throw Utils.parameterError(
            method,
            p,
            "%s map value '%s' converted to null by %s for key '%s'.",
            mapName,
            value,
            converter.getClass().getName(),
            key);
      }
      action.accept(key, converted);
    }
  }

  static final class RelativeUrl extends ParameterHandler<Object> {
    private final Method method;
    private final int p;

    RelativeUrl(Method method, int p) {
      this.method = method;
      this.p = p;
    }

    @Override
    void apply(RequestBuilder builder, @Nullable Object value) {
      if (value == null) {
        throw Utils.parameterError(method, p, "@Url parameter is null.");
      }
      builder.setRelativeUrl(value);
    }
  }

  static final class Header<T> extends ParameterHandler<T> {
    private final String name;
    private final Converter<T, String> valueConverter;
    private final boolean allowUnsafeNonAsciiValues;

    Header(String name, Converter<T, String> valueConverter, boolean allowUnsafeNonAsciiValues) {
      this.name = Objects.requireNonNull(name, "name == null");
      this.valueConverter = valueConverter;
      this.allowUnsafeNonAsciiValues = allowUnsafeNonAsciiValues;
    }

    @Override
    void apply(RequestBuilder builder, @Nullable T value) throws IOException {
      if (value == null) return; // Skip null values.

      String headerValue = valueConverter.convert(value);
      if (headerValue == null) return; // Skip converted but null values.

      builder.addHeader(name, headerValue, allowUnsafeNonAsciiValues);
    }
  }

  static final class Path<T> extends ParameterHandler<T> {
